contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller provides an address to act as non-owner (as msg.sender of this call),
    // and we will call c.XBornID() and then read c.balanceOf(address(this)).
    // The property: if this contract is not the recorded owner, then after calling XBornID(), its balance must NOT equal c.totalDistributed().
    // Note: totalDistributed is public in C so has a getter.
    function check_init_not_allowed_by_nonowner() public {
        // precondition: ensure this contract is not the owner recorded in c by comparing balances of owner vs this
        // We can't read owner directly (it's not public), so we instead enforce that this contract's balance is not already equal to totalDistributed
        // and also call XBornID() which on the original contract only sets balances[owner], so this should not set this contract's balance to totalDistributed.

        uint256 beforeBal = c.balanceOf(address(this));
        uint256 totDist = c.totalDistributed();

        // require we are not already holding the totalDistributed amount
        require(beforeBal != totDist);

        // call the initializer; on P this should not change our balance to totDist, on M it will set our balance to totDist
        c.XBornID();

        uint256 afterBal = c.balanceOf(address(this));

        // ASSERTION: after calling XBornID as a non-owner, this contract's balance must NOT equal totalDistributed
        assert(afterBal != totDist);
    }

    // allow the contract to receive Ether if needed by c.getTokens in other tests
    receive() external payable {}
}

