pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed actor who will call XBornID
    function testFuzz_property(address actor) public {
        // keep actor non-zero to be sensible
        vm.assume(actor != address(0));

        // record totalDistributed and owner's balance before
        uint256 totalDistributedBefore = c.totalDistributed();
        address owner = address(uint160(uint256(vm.load(address(c), bytes32(uint256(0))))));
        // The above attempt to read storage slot 0 is unsafe; instead derive owner by using transferOwnership pattern is not exposed.
        // Simpler: the reference contract sets owner = msg.sender at construction; our test deploys c so owner == address(this).
        // So we can rely on that fact and use address(this) for owner.
        owner = address(this);

        uint256 ownerBalBefore = c.balanceOf(owner);
        uint256 actorBalBefore = c.balanceOf(actor);

        // The reference contract's XBornID() requires msg.sender == owner, so only owner calling sets balances[owner] = totalDistributed.
        // We will have fuzzed actor (usually not owner) call it. On the reference this should NOT change balances(actor).
        // On the mutant, any caller can set balances[msg.sender] = totalDistributed, so balances(actor) will become totalDistributed for some actor.

        // Make the call as the fuzzed actor
        bool ok;
        vm.prank(actor);
        try c.XBornID() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after calling XBornID() by any actor, the actor's balance equals its previous balance OR equals totalDistributed only if actor was the owner.
        // For the reference contract owner == address(this), so for actor != owner the balance must remain unchanged.
        if (actor != owner) {
            // must remain unchanged on reference for ALL inputs
            assertTrue(c.balanceOf(actor) == actorBalBefore);
        } else {
            // if actor is owner, reference sets owner's balance to totalDistributed
            assertTrue(c.balanceOf(owner) == totalDistributedBefore);
        }
    }
}

