    function testFuzz_property(address actor) public {
        // keep actor non-zero to be a valid actor and avoid trivial zero-address behavior
        vm.assume(actor != address(0));

        // record balances before
        uint256 ownerBalBefore = c.balanceOf(address(this)); // not owner; contract created c with owner = msg.sender at deployment (this setUp)
        // determine owner by calling transferOwnership then reading? Owner is not exposed; but reference behavior: only deployer (this) is owner.
        // We observe public behavior: after correct contract XBornID, balances(owner) == totalDistributed and calling XBornID by non-owner should NOT set caller's balance to totalDistributed.

        // Ensure actor has ETH to call if needed (XBornID is nonpayable here)
        vm.deal(actor, 1 ether);

        // make the call as actor
        vm.prank(actor);
        bool ok;
        try c.XBornID() {
            ok = true;
        } catch {
            ok = false;
        }

        // On the correct contract: only the deployer (owner) had been able to set balances(owner)=totalDistributed in constructor-like function XBornID; because owner==deployer (this) and test calls XBornID as a different actor, the caller's balance should NOT equal totalDistributed. We therefore assert caller's balance != totalDistributed.
