contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: owner sets approval for spender of approveAmount, then spender calls transferFrom to transfer transferAmount to recipient.
    // We assert that allowance(owner, spender) after transfer equals initial allowance minus transferAmount (i.e., it decreased).
    function run(address owner, address spender, address recipient, uint256 approveAmount, uint256 transferAmount) public {
        // Preconditions to make calls sensible
        require(owner != address(0));
        require(spender != address(0));
        require(recipient != address(0));
        require(approveAmount >= transferAmount);

        // Ensure owner has enough balance to cover transferAmount by relying on c.balanceOf(owner) >= transferAmount.
        // If not, test is not applicable; require it.
        require(c.balanceOf(owner) >= transferAmount);

        // owner must call approve on c. We must make the call from owner; but we can only call c from this contract.
        // To simulate calls from owner and spender, we use the ERC20 approve/transferFrom functions which act on msg.sender.
        // However, per constraints we can only interact through c from this contract; thus we use allowance/approve pattern by
        // having this contract ask owner to be msg.sender is impossible. To satisfy the requirement while keeping interaction
        // only through c, we use the public approve function by assuming 'owner' equals address(this).
        // So constrain owner == address(this) to permit calling approve as owner.
        require(owner == address(this));
        require(spender != address(this));

        // Approve spender for approveAmount (call made by owner == this contract)
        bool ok = c.approve(spender, approveAmount);
        require(ok);

        // Read allowance before transfer
        uint256 before = c.allowance(owner, spender);

        // Now perform transferFrom by calling c.transferFrom as spender. We cannot call as spender address directly, so require spender == address(this)
        // To perform transferFrom from spender perspective, we must have spender == address(this). Therefore adjust constraints: spender must be this contract.
        // Enforce that so calls are valid.
        require(spender == address(this));

        // Make the transferFrom call from this contract (acting as spender)
        bool ok2 = c.transferFrom(owner, recipient, transferAmount);
        require(ok2);

        // Read allowance after transfer
        uint256 after = c.allowance(owner, spender);

        // The property: after == before - transferAmount
        assert(after == before - transferAmount);
    }

    // receive/fallback to accept ETH if needed by c (not used but allowed)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address owner, address spender, address to, uint256 amount) public payable {
        // preconditions: owner must not be zero, spender must not be zero, to must not be zero
        require(owner != address(0) && spender != address(0) && to != address(0));
        // Ensure there is an allowance at least 'amount' and owner has enough balance: caller must be spender to invoke transferFrom
        // We cannot call c.approve as owner from this contract directly since msg.sender would be this contract; instead we rely on the general observable rule.
        // The test will call transferFrom as this contract (msg.sender), so 'spender' must be this contract's address. Enforce that.
        require(spender == address(this));

        // Record allowance before the call
        uint256 before = c.allowance(owner, spender);

        // The call under test: perform transferFrom from owner to 'to' of 'amount'
        // This will succeed on the original contract only when amount <= balances[owner] and amount <= allowance(owner, spender)
        // We invoke it regardless; if it reverts the transaction will revert the whole test and fail — so we constrain inputs to allow success.
        require(amount <= before);
        uint256 ownerBalance = c.balanceOf(owner);
        require(amount <= ownerBalance);

        // perform transferFrom; this contract acts as spender
        c.transferFrom(owner, to, amount);

        // allowance after
        uint256 afterVal = c.allowance(owner, spender);

        // general rule: allowance decreased by exactly amount
        assert(afterVal + amount == before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // owner: address from which tokens will be transferred
    // spender: address that calls transferFrom (must be msg.sender in c context; here we simulate by having this contract be the spender)
    // recipient: address to receive tokens
    // initialAllowance: amount approved for this contract to spend from owner
    // firstAmount: amount transferred in first transferFrom
    // secondAmount: amount transferred in second transferFrom

    function run(address owner, address recipient, uint256 initialAllowance, uint256 firstAmount, uint256 secondAmount) public payable {
        // Preconditions to ensure meaningful scenario and to avoid obvious failures unrelated to allowance decrement:
        // - this contract must not be the zero address
        // - owner and recipient distinct
        // - initialAllowance >= firstAmount and initialAllowance < firstAmount + secondAmount (so second transfer would exceed allowance if allowance is decremented)
        // - owner has enough balance to cover both transfers
        require(owner != address(0) && recipient != address(0) && owner != recipient, true);
        require(initialAllowance >= firstAmount, true);
        require(initialAllowance < firstAmount + secondAmount, true);

        // We cannot call approve on behalf of owner because we are not owner; instead the test assumes the environment prepared an allowance
        // For safety, read owner's balance and require it's enough to cover both transfer attempts.
        uint256 ownerBal = c.balanceOf(owner);
        require(ownerBal >= firstAmount + secondAmount, true);

        // Also require that the current allowance from owner to this contract equals initialAllowance
        uint256 allow = c.allowance(owner, address(this));
        require(allow == initialAllowance, true);

        // First transferFrom should succeed (consuming allowance in original contract)
        bool ok1 = false;
        try c.transferFrom(owner, recipient, firstAmount) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // Second transferFrom attempt: in the correct contract P it should fail because allowance was decreased and remaining allowance < secondAmount
        bool ok2 = false;
        try c.transferFrom(owner, recipient, secondAmount) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Assert the general rule: it is not possible for both transfers to succeed when their sum exceeds the original allowance.
        assert(!(ok1 && ok2));
    }

    receive() external payable { }
}

