        // set up: owner must have sufficient balance and initial allowance must be at least amount
        // We rely on the existing contract state: caller of this test cannot directly set balances/allowances,
        // but we require the allowance observed before to be >= amount so transferFrom can succeed in P.
        uint256 before = c.allowance(owner, spender);
        require(before >= amount);
        // perform the transferFrom as spender (this contract) by forwarding the call through c.
        // But transferFrom is external; we need to call it from this contract, which will be msg.sender for c.transferFrom.
        // The test invokes the transferFrom which will succeed under the precondition.
        c.transferFrom(owner, to, amount);
