contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address ownerAddr, address spenderAddr, address to, uint256 amount) public payable {
        require(ownerAddr != address(0) && spenderAddr != address(0) && to != address(0));
        // Precondition: spender has at least `amount` allowance from owner and owner has enough balance
        require(c.allowance(ownerAddr, spenderAddr) >= amount);
        require(c.balanceOf(ownerAddr) >= amount);

        uint256 beforeAllowance = c.allowance(ownerAddr, spenderAddr);
        c.transferFrom(ownerAddr, to, amount);
        uint256 afterAllowanceVal = c.allowance(ownerAddr, spenderAddr);
