contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: owner balance seed (as uint to derive addresses and amounts), approveAmount, transferAmount
    function testFuzz_property(uint256 seed, uint256 approveAmount, uint256 transferAmount) public {
        // keep addresses wide but valid
        address owner = address(uint160(seed));
        address spender = address(uint160(seed + 1));
        address recipient = address(uint160(seed + 2));

        // Bound amounts to reasonable ranges to avoid overflow and to fit within totalDistributed
        approveAmount = bound(approveAmount, 1, 1e24); // up to large but safe
        transferAmount = bound(transferAmount, 1, approveAmount); // ensure transferAmount <= approveAmount

        // Ensure owner has tokens to allow transferFrom to succeed: give owner some distribution by calling XBornID via prank
        // XBornID sets balances[owner] = totalDistributed only when called by contract deployer in original; but in C XBornID requires msg.sender == owner (owner was contract deployer), so to give tokens we instead simulate distribution by having contract owner transfer tokens to 'owner' address.
        // The contract deployer is address(this) in setUp? Actually c was deployed by test contract, so test contract is owner. We'll transfer from test contract (owner) to our owner address.

        // compute minimal amounts to transfer: ensure contract owner (this test) has initial totalDistributed tokens
        uint256 initialDistributed = c.totalDistributed();
        // make sure we do not transfer more than the contract owner's balance
        uint256 give = bound(approveAmount, 1, initialDistributed);

        // transfer tokens from deployer (which is this test contract) to the 'owner' address
        // the test contract is the owner of C since it deployed it in setUp
        // use vm.prank to act as deployer (this test contract) when calling transfer
        vm.prank(address(this));
        bool ok = c.transfer(owner, give);
        // require transfer succeeded in the reference; if it failed, skip (assume)
        vm.assume(ok);

        // Now have 'owner' approve 'spender' for approveAmount
        vm.prank(owner);
        bool app = c.approve(spender, approveAmount);
        vm.assume(app);

        // Record allowance before transferFrom
        uint256 before = c.allowance(owner, spender);

        // Make sure balances allow transferFrom: owner balance >= transferAmount
        // If not, skip
        vm.assume(c.balanceOf(owner) >= transferAmount);

        // Have spender call transferFrom(owner, recipient, transferAmount)
        vm.prank(spender);
        bool tf = c.transferFrom(owner, recipient, transferAmount);
        vm.assume(tf);

        // Single assertion: allowance should have decreased by transferAmount in the correct contract
        uint256 after = c.allowance(owner, spender);
        assertTrue(after + transferAmount == before);
    }
}

